/* v1271 LANGUAGES step 2 (Phil 4 Nov 2026: "I need everything thats translatable to be translated"): ewT() is t() for code whose
   function has its own local `t`; langMsg(s) turns an English server error (r.error stays English for the code's own checks) into the
   player's language: the server sends {error, code, vars} (server/error-codes.js) and _apiRaw notes the translation of each error it sees. */
function ewT(key,vars){ return t(key,vars); }
const LANG_ERR=new Map();
function langErrNote(j){ if(!j||typeof j!=='object'||typeof j.error!=='string'||!j.code) return;
  const k='err.'+j.code; if(!(k in EW_LANG_EN)) return; LANG_ERR.set(j.error,{k,vars:j.vars||null}); }
function langMsg(s){ if(s==null||LANG.cur==='en') return s; const e=LANG_ERR.get(String(s)); return e?(t(e.k,e.vars)||s):s; }
